exact_commands.local_cache_probe:
python - <<'PY'
from huggingface_hub import snapshot_download
from pathlib import Path
models=['Rostlab/ProstT5','Rostlab/ProstT5_fp16']
caches=[Path.home()/'.cache'/'huggingface'/'hub', Path('/private/tmp/catalytic-earth-hf-cache/hub')]
for model in models:
    for cache in caches:
        print(f'## model={model} cache={cache}')
        try:
            print(snapshot_download(model, cache_dir=str(cache), local_files_only=True))
        except Exception as e:
            print(type(e).__name__, str(e).replace('\n',' ')[:800])
PY
